(()=>{
 const frames=[{"src":"data:image/webp;base64,","kind":"wide","alt":"طلاب يتناقشون في مجموعة صغيرة داخل القاعة"},{"src":"data:image/webp;base64,","kind":"wide","alt":"عدة مجموعات طلابية تتناقش في الفصل"},{"src":"data:image/webp;base64,","kind":"portrait","alt":"لقطة مقربة لأحد المشاركين أثناء حديثه"},{"src":"data:image/webp;base64,","kind":"square","alt":"مجموعة طلاب تتبادل الآراء في جانب القاعة"},{"src":"data:image/webp;base64,","kind":"wide","alt":"طلاب يتحاورون حول مشروعهم"},{"src":"data:image/webp;base64,","kind":"portrait","alt":"لقطة مقربة لأحد المشاركين وهو يستمع"},{"src":"data:image/webp;base64,","kind":"square","alt":"مجموعة نقاش أخرى بالقرب من النافذة"},{"src":"data:image/webp;base64,","kind":"wide","alt":"طلاب جالسون في حلقة نقاش"},{"src":"data:image/webp;base64,","kind":"portrait","alt":"صورة قريبة لطالب يستمع بانتباه"},{"src":"data:image/webp;base64,","kind":"square","alt":"أفراد يجلسون في منتصف نقاش طلابي"},{"src":"data:image/webp;base64,","kind":"square","alt":"مشاركة طلابية مع إيماءات أثناء الحوار"},{"src":"data:image/webp;base64,","kind":"wide","alt":"فريقان طلابيان في نقاش منفصل داخل القاعة"},{"src":"data:image/webp;base64,","kind":"square","alt":"نقاش بين عدة طلاب حول طاولة"},{"src":"data:image/webp;base64,","kind":"square","alt":"مشاركة أفراد يجلسون في حلقة"},{"src":"data:image/webp;base64,","kind":"wide","alt":"مشهد واسع لمناقشة طلابية"},{"src":"data:image/webp;base64,","kind":"wide","alt":"مجموعة طلاب تتشارك الحوار وجها لوجه"},{"src":"data:image/webp;base64,","kind":"square","alt":"طالبات وطلاب يناقشون مسألة ضمن فرقهم"}];
 const groups=document.querySelectorAll('#cm-gallery .cm-group');
 const widthMap={wide:258,square:216,portrait:168};
 for(const g of groups){const duplicate=g.getAttribute('aria-hidden')==='true';for(const item of frames){
   const f=document.createElement('figure');f.className='cm-photo';f.style.setProperty('--cm-w',widthMap[item.kind]+'px');
   const img=document.createElement('img');img.src=item.src;img.alt=duplicate?'':item.alt;img.draggable=false;img.decoding='async';img.loading=duplicate?'lazy':'eager';
   f.append(img);g.append(f);
 }}
 const root=document.getElementById('cm-gallery'),btn=document.getElementById('cm-toggle');if(!root||!btn)return;
 const label=btn.querySelector('.cm-control-text'),glyph=btn.querySelector('.cm-icon');
 function update(){const p=root.dataset.paused==='true';btn.setAttribute('aria-pressed',String(p));btn.setAttribute('aria-label',p?'استئناف حركة الصور':'إيقاف حركة الصور');label.textContent=p?'تشغيل':'إيقاف';glyph.textContent=p?'▶':'Ⅱ';}
 btn.addEventListener('click',()=>{root.dataset.paused=String(root.dataset.paused!=='true');update()});
 const mo=new MutationObserver(()=>{root.setAttribute('dir',document.documentElement.dir==='ltr'?'ltr':'rtl')});
 mo.observe(document.documentElement,{attributes:true,attributeFilter:['dir']});
 update();
})()